const failed = tests.filter(t => t.status == "fail");
const rate = len(failed) / len(tests);
const verdict = if (!failed) { "pass" } else if (rate < 0.1) { "flaky" } else { "fail" };
{
  verdict,
  summary: `${len(failed)} of ${len(tests)} failed`,
  slowest: failed.sortBy(t => t.ms, "desc").slice(0, 3).map(({name, ms}) => `${name} ${ms}ms`),
  owner: failed.find(t => t.owner != null)?.owner ?? "unknown",
}
